{
  "scenes": [
    {
      "kind": "wait",
      "start_ms": 0,
      "end_ms": 1000,
      "description": "视频开始于3D打印类App首页（模型推荐流），顶部显示设备名与空闲状态，并有 model 处理完成的提示横幅及去打印入口，页面展示推荐模型卡片与底部导航。"
    },
    {
      "kind": "navigation",
      "start_ms": 1000,
      "end_ms": 2000,
      "description": "点击首页顶部搜索入口，跳转到搜索页，页面展示搜索框、搜索历史标签与热搜榜列表，软键盘自动弹出。"
    },
    {
      "kind": "wait",
      "start_ms": 2000,
      "end_ms": 4000,
      "description": "搜索页保持停留，搜索框为空，热搜榜与搜索历史可见，键盘处于可输入状态，未进行操作。"
    },
    {
      "kind": "input",
      "start_ms": 4000,
      "end_ms": 9000,
      "description": "在搜索框通过拼音键盘输入并选择候选词，先输入两个字组成搜索词前半部分（姓名）。"
    },
    {
      "kind": "input",
      "start_ms": 9000,
      "end_ms": 12000,
      "description": "继续输入第三个字，期间曾误选候选词使搜索框出现多余字，随后删除并重新选择，最终搜索框内容为姓名牌。"
    },
    {
      "kind": "interaction",
      "start_ms": 12000,
      "end_ms": 12500,
      "description": "点击搜索按钮提交搜索词，键盘收起，页面切换到搜索结果列表。"
    },
    {
      "kind": "wait",
      "start_ms": 12500,
      "end_ms": 14000,
      "description": "搜索结果页加载并展示两个模型卡片（姓名牌、Max挂牌）及AI创作推广横幅，卡片图片由占位态加载为完整图片。"
    },
    {
      "kind": "interaction",
      "start_ms": 14000,
      "end_ms": 15000,
      "description": "点击搜索结果中第一个模型卡片（姓名牌），进入该模型详情页，展示模型大图、标签、打印人数、模型文件信息与底部操作按钮。"
    },
    {
      "kind": "wait",
      "start_ms": 15000,
      "end_ms": 16000,
      "description": "模型详情页停留，可见模型文件条目（含预计时长、材料克数、尺寸）与底部旋钮设置、去编辑两个按钮。"
    },
    {
      "kind": "navigation",
      "start_ms": 16000,
      "end_ms": 17000,
      "description": "点击去编辑按钮，跳转到编辑模型页，页面先黑屏并显示正在加载的加载动画。"
    },
    {
      "kind": "wait",
      "start_ms": 17000,
      "end_ms": 18500,
      "description": "编辑模型页加载完成，显示3D预览空间、模型尺寸提示、文本输入区（含默认文本）与底部主按钮，预览中的模型逐步渲染出现。"
    },
    {
      "kind": "interaction",
      "start_ms": 18500,
      "end_ms": 20000,
      "description": "点击文本输入框唤起键盘，并删除输入框中原有的默认文本，输入框变为空占位态。"
    },
    {
      "kind": "input",
      "start_ms": 20000,
      "end_ms": 24000,
      "description": "切换键盘到英文布局，输入两个英文字母UI作为新文本的前缀。"
    },
    {
      "kind": "input",
      "start_ms": 24000,
      "end_ms": 27000,
      "description": "切回拼音键盘继续输入中文候选词并上屏，与前面英文字母组合成完整文本UI自动化。"
    },
    {
      "kind": "interaction",
      "start_ms": 27000,
      "end_ms": 28000,
      "description": "收起键盘，编辑模型页完整显示，文本输入框内容为UI自动化，底部主按钮变为生成模型。"
    },
    {
      "kind": "wait",
      "start_ms": 28000,
      "end_ms": 31000,
      "description": "编辑模型页停留，3D预览中模型仍显示旧文本浮雕，未立即变化，等待用户操作。"
    },
    {
      "kind": "interaction",
      "start_ms": 31000,
      "end_ms": 32000,
      "description": "点击生成模型按钮，触发模型重新生成。"
    },
    {
      "kind": "wait",
      "start_ms": 32000,
      "end_ms": 34500,
      "description": "页面中央显示生成中的加载遮罩，预览中的模型暂时变暗，等待生成完成。"
    },
    {
      "kind": "wait",
      "start_ms": 34500,
      "end_ms": 36500,
      "description": "生成完成，遮罩消失，模型尺寸提示更新为新尺寸，预览模型浮雕更新为新文本，底部主按钮变为去打印。"
    },
    {
      "kind": "interaction",
      "start_ms": 36500,
      "end_ms": 37500,
      "description": "点击去打印按钮，触发打印前准备流程。"
    },
    {
      "kind": "wait",
      "start_ms": 37500,
      "end_ms": 41000,
      "description": "页面显示准备打印中的加载遮罩，持续数秒后页面切换。"
    },
    {
      "kind": "navigation",
      "start_ms": 41000,
      "end_ms": 42500,
      "description": "进入打印编辑（切片摆放）页，黑色3D场景加载，随后显示智能匹配参数的加载提示。"
    },
    {
      "kind": "wait",
      "start_ms": 42500,
      "end_ms": 44000,
      "description": "打印编辑页显示AI引擎优化完成的提示，随后提示消失，场景中出现黄色模型与打印空间边框，底部显示缩放比例与下一步按钮。"
    },
    {
      "kind": "interaction",
      "start_ms": 44000,
      "end_ms": 45000,
      "description": "点击下一步按钮，页面显示正在校验模型的加载提示。"
    },
    {
      "kind": "wait",
      "start_ms": 45000,
      "end_ms": 46500,
      "description": "弹出耗材颜色确认弹窗，提示当前使用的官方耗材颜色为黄色，含修改设置与确认按钮及不再提醒选项。"
    },
    {
      "kind": "interaction",
      "start_ms": 46500,
      "end_ms": 47000,
      "description": "在耗材颜色确认弹窗中点击确认，弹窗关闭回到打印编辑页。"
    },
    {
      "kind": "wait",
      "start_ms": 47000,
      "end_ms": 48000,
      "description": "随即弹出任务冲突对话框，提示当前有一个正在处理的任务请去处理，含取消与去处理两个按钮。"
    },
    {
      "kind": "interaction",
      "start_ms": 48000,
      "end_ms": 48800,
      "description": "在任务冲突对话框中点击去处理，跳转到模型打印预览页。"
    },
    {
      "kind": "wait",
      "start_ms": 48800,
      "end_ms": 50500,
      "description": "模型打印预览页加载并渲染模型，显示的是一个与本次编辑无关的旧任务模型（黄色马形与字母形），并给出预计时间、模型耗材与支撑耗材信息。"
    },
    {
      "kind": "interaction",
      "start_ms": 50500,
      "end_ms": 51500,
      "description": "在旧任务预览页点击取消打印按钮，弹出确认要取消任务的对话框。"
    },
    {
      "kind": "interaction",
      "start_ms": 51500,
      "end_ms": 52500,
      "description": "在取消确认对话框中点击确定，页面显示已取消模型处理状态，底部变为重新编辑与返回按钮。"
    },
    {
      "kind": "navigation",
      "start_ms": 52500,
      "end_ms": 53500,
      "description": "点击返回按钮，回到打印编辑页（姓名牌黄色模型场景）。"
    },
    {
      "kind": "wait",
      "start_ms": 53500,
      "end_ms": 54500,
      "description": "返回后再次弹出耗材颜色确认弹窗，内容与之前一致。"
    },
    {
      "kind": "interaction",
      "start_ms": 54500,
      "end_ms": 55000,
      "description": "再次点击确认关闭耗材颜色弹窗，页面短暂显示收集模型信息的加载提示。"
    },
    {
      "kind": "wait",
      "start_ms": 55000,
      "end_ms": 56000,
      "description": "打印编辑页重新计算模型信息，尺寸暂显示为0，随后自动进入模型打印预览页。"
    },
    {
      "kind": "wait",
      "start_ms": 56000,
      "end_ms": 62000,
      "description": "模型打印预览页显示待打印任务生成与分析流程的逐步进度（生成任务、分析打印时间、分析消耗克数、分析尺寸、等待处理），进度条保持0.0%，并提供处理完成后直接打印与取消处理按钮。"
    },
    {
      "kind": "wait",
      "start_ms": 62000,
      "end_ms": 64000,
      "description": "预览页重新加载并渲染本次姓名牌模型，显示黄色姓名牌3D模型及预计时间、耗材克数信息与设备状态提示。"
    },
    {
      "kind": "interaction",
      "start_ms": 64000,
      "end_ms": 65500,
      "description": "在本次任务的预览页点击取消打印按钮，弹出确认要取消任务的对话框。"
    },
    {
      "kind": "interaction",
      "start_ms": 65500,
      "end_ms": 67000,
      "description": "点击确定确认取消，页面显示已取消模型处理状态，底部为重新编辑与返回按钮。"
    },
    {
      "kind": "navigation",
      "start_ms": 67000,
      "end_ms": 68500,
      "description": "点击返回按钮，回到打印编辑页，随后再次返回上一层编辑模型页。"
    },
    {
      "kind": "navigation",
      "start_ms": 68500,
      "end_ms": 70500,
      "description": "从编辑模型页继续返回，依次回到模型详情页与搜索结果页。"
    },
    {
      "kind": "navigation",
      "start_ms": 70500,
      "end_ms": 73000,
      "description": "从搜索结果页返回搜索页并最终回到App首页推荐流，键盘收起。"
    },
    {
      "kind": "wait",
      "start_ms": 73000,
      "end_ms": 75376,
      "description": "视频结束前停留在首页推荐流，页面内容与开头一致，顶部仍有处理完成提示横幅，无进一步操作。"
    }
  ],
  "questions": [
    "00:48出现的正在处理的任务对话框所指向的旧任务，是否就是00:50预览页中显示的马形与字母形模型？",
    "第一次取消的旧任务与第二次取消的本次姓名牌任务，是否为两个独立任务还是同一任务被重复处理？",
    "00:54返回打印编辑页后再次弹出耗材确认弹窗，是否因为取消任务后流程重新发起所致？",
    "00:56至01:02的分析进度期间，用户是否点击了处理完成后直接打印，还是等待自动完成？",
    "视频结尾返回首页后，顶部处理完成横幅对应的是哪一次任务的结果？"
  ]
}

